-- Jeu de LecteurPublicationsBodacc (« Publications BODACC », PROC_GESTBOD), lot 11 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Annonces 2110201-2110205. Ce qui est retenu ou ecarte, et pourquoi : PROC_GESTBOD.attendu.
-- v2.BODACC est creee par PROC_FIBEN.sql (sa cle de banc BDCCR_ID_BDCCR, recue ici la meme valeur que BDCCR_ID_BDCRC, la cle de
-- RIG_DEV) ; les colonnes lues lui sont ajoutees si elles manquent, aux types de RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV,
-- lu le 27/11/2026). Aucune annonce n'a d'evenement de procedure : elles n'entrent dans aucun ecran des evenements, des procedures
-- collectives ou des preventions ; sans controle qualite, elles n'entrent pas dans PROC_SURVBOD.
IF OBJECT_ID(N'v2.BODACC') IS NULL
    CREATE TABLE v2.BODACC (BDCCR_ID_BDCCR int NOT NULL PRIMARY KEY, BDCCR_TYPE_BODACC varchar(5) NULL, BDCCR_DATE_PUBLICITE datetime NULL);
IF COL_LENGTH('v2.BODACC', 'BDCCR_ID_BDCRC') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_ID_BDCRC int NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_ID_EVNPR') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_ID_EVNPR int NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_DATE_ENVOI') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_DATE_ENVOI datetime NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_ETAT_BODACC') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_ETAT_BODACC varchar(2) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_NUMERO_ANNONCE') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_NUMERO_ANNONCE varchar(15) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_MOTIF_REJET_BODACC_1') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_MOTIF_REJET_BODACC_1 varchar(255) NULL;
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR int NOT NULL PRIMARY KEY, EVNPR_ID_INSTN int NULL, EVNPR_NUM_ORDRE smallint NULL,
        EVNPR_CODE_EVE_PRO varchar(10) NOT NULL, EVNPR_DATE datetime NULL, EVNPR_SURVENU bit NULL, EVNPR_DELAI_EXPIRE bit NULL);
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_PRCLL') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_PRCLL int NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_PREVE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_PREVE int NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_PC varchar(11) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE varchar(250) NULL;
IF OBJECT_ID(N'v2.PREVENTION') IS NULL
    CREATE TABLE v2.PREVENTION (PREVE_ID_PREVE int NOT NULL PRIMARY KEY, PREVE_NUM_PRV varchar(10) NULL, PREVE_NOM_AFFAIRE varchar(250) NULL);

EXEC sp_executesql N'
INSERT INTO v2.BODACC (BDCCR_ID_BDCCR, BDCCR_ID_BDCRC, BDCCR_TYPE_BODACC, BDCCR_ETAT_BODACC, BDCCR_DATE_ENVOI, BDCCR_NUMERO_ANNONCE,
                       BDCCR_MOTIF_REJET_BODACC_1) VALUES
    -- rejetee (9), publicite de procedure (P) : a traiter
    (2110201, 2110201, ''P1'', ''9'', ''20010402'', ''A2110201'', ''Adresse incomplète''),
    -- rejetee, sans motif ni numero : a traiter -- elle se renvoie (PROC_GESTBOD.gestes)
    (2110202, 2110202, ''P2'', ''9'', ''20010403'', NULL, NULL),
    -- deja remise a renvoyer (3) : a renvoyer, figee
    (2110203, 2110203, ''P1'', ''3'', ''20010404'', ''A2110203'', ''Nom tronqué''),
    -- rejetee mais d''un type hors publicite de procedure (N) : ecartee -- jumelle 2110201
    (2110204, 2110204, ''N1'', ''9'', ''20010402'', ''A2110204'', ''Adresse incomplète''),
    -- publiee a verifier (5) : un certificat, dont la liste exige une date -- ecartee, jumelle 2110201
    (2110205, 2110205, ''P1'', ''5'', ''20010402'', ''A2110205'', NULL);';

-- Pour les CERTIFICATS DE PARUTION et les CONTROLES NON CONFORMES (lot 11, reprise : PROC_GESTBOD.recherches et .gestes) : des
-- annonces de 2001 (PROC_SURVBOD ne lit que les parutions depuis 2008), dont deux sur l'evenement 2110251 (BANC11B, du 01/04/2001,
-- sans instance, PC ni prevention). Colonnes ajoutees si un jeu precedent ne les a pas posees, aux types de RIG_DEV.
IF COL_LENGTH('v2.BODACC', 'BDCCR_NUM_PARUTION') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_NUM_PARUTION varchar(10) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_CONTROLE_QUALITE') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_CONTROLE_QUALITE nvarchar(max) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_DATE_EP_SUPPR') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_DATE_EP_SUPPR datetime NULL;
EXEC sp_executesql N'
INSERT INTO v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR, EVNPR_CODE_EVE_PRO, EVNPR_DATE, EVNPR_SURVENU, EVNPR_DELAI_EXPIRE) VALUES
    (2110251, ''BANC11B'', ''20010401'', 1, 0);
UPDATE v2.BODACC SET BDCCR_NUMERO_ANNONCE = ''A2110205'' WHERE BDCCR_ID_BDCRC = 2110205;
INSERT INTO v2.BODACC (BDCCR_ID_BDCCR, BDCCR_ID_BDCRC, BDCCR_TYPE_BODACC, BDCCR_ETAT_BODACC, BDCCR_DATE_ENVOI, BDCCR_DATE_PUBLICITE,
                       BDCCR_NUM_PARUTION, BDCCR_NUMERO_ANNONCE, BDCCR_ID_EVNPR, BDCCR_CONTROLE_QUALITE, BDCCR_DATE_EP_SUPPR) VALUES
    -- parue le 10/04 (parution P2110) et deja verifiee (6)
    (2110206, 2110206, ''P1'', ''6'', ''20010402'', ''20010410'', ''P2110'', ''A2110206'', NULL, NULL, NULL),
    -- rectifiee, a verifier (10), sur l''evenement 2110251, avec un controle qualite : un certificat ET un controle non conforme
    (2110207, 2110207, ''P2'', ''10'', ''20010406'', ''20010410'', ''P2110'', ''A2110207'', 2110251, N''Capital manquant'', NULL),
    -- type N (hors P%) avec un controle qualite : un controle non conforme seulement (le controle ne filtre pas le type)
    (2110208, 2110208, ''N1'', ''5'', ''20010406'', NULL, NULL, ''A2110208'', 2110251, N''Siège absent'', NULL),
    -- a verifier, son evenement supprime le 01/04 (BDCCR_DATE_EP_SUPPR) : la date d''EP la trouve
    (2110209, 2110209, ''P1'', ''5'', NULL, NULL, NULL, ''A2110209'', NULL, NULL, ''20010401'');';

-- Pour « Éditer » (EcrivainPublicationsBodacc, lot 11, reprise 6 : PROC_GESTBOD.gestes). Deux certificats de parution a verifier (5),
-- de mai 2001 (aucune recherche de ce jeu ne vise mai) : 2110210 sur l'evenement 2110261 de la PC 1400101 (PROC_CHM.sql, son mandataire
-- MDJ 1400551 en mission), 2110211 sur l'evenement 2110262 de la prevention 1400201 (PROC_CHM.sql, sans mandataire). Le mandataire
-- recoit une adresse (rec.Adresse 2110281 : toque, pre-adresse, voie, BP, cedex -- EditionsEvenement.BlocAdresseAsync), un courriel et un coffre-fort
-- demarre. Colonnes et tables ajoutees si un jeu precedent ne les a pas posees, aux types de RIG_DEV (SQL-DEV\DEV, lu le 27/11/2026).
IF COL_LENGTH('v2.BODACC', 'BDCCR_NUMERO_SOURCE') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_CODE_EP_SUPPR') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_CODE_EP_SUPPR varchar(10) NULL;
IF COL_LENGTH('v2.BODACC', 'BDCCR_ID_PREC_BOD') IS NULL ALTER TABLE v2.BODACC ADD BDCCR_ID_PREC_BOD int NULL;
IF OBJECT_ID(N'v2.TYPE_BODACC') IS NULL
    CREATE TABLE v2.TYPE_BODACC (R_TYPEBODACC_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPEBODACC_BORDEREAU varchar(3) NULL);
IF COL_LENGTH('v2.TYPE_BODACC', 'R_TYPEBODACC_LIBELLE_ECRAN') IS NULL ALTER TABLE v2.TYPE_BODACC ADD R_TYPEBODACC_LIBELLE_ECRAN varchar(35) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ID_ADRBS') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ID_ADRBS int NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ADRESSE_MAIL') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ADRESSE_MAIL varchar(1000) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_NOM_COFFRE') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_NOM_COFFRE varchar(100) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_DATE_DEMARRAGE_COFFRE') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_DATE_DEMARRAGE_COFFRE datetime NULL;
-- La reference du mandataire sur le certificat (REFERENCE_DESTINATAIRE = GRRPC_NUMERO_INTERNE, DestinatairesEditionsLot2.cs:1647 ;
-- reprise 7) ; varchar(15) dans RIG_DEV (lu le 27/11/2026).
IF COL_LENGTH('v2.GERER_PC', 'GRRPC_NUMERO_INTERNE') IS NULL ALTER TABLE v2.GERER_PC ADD GRRPC_NUMERO_INTERNE varchar(15) NULL;
IF OBJECT_ID(N'v2.TYPE_VOIE') IS NULL
    CREATE TABLE v2.TYPE_VOIE (R_TYPEVOIE_VALEUR varchar(4) NOT NULL PRIMARY KEY, R_TYPEVOIE_LIBELLE_ECRAN varchar(35) NOT NULL);
-- Le nom du greffe de l'etat (RigGreffe.TypeEtNomGreffeMaj : EcrivainPublicationsBodacc.GreffeNomAsync), le greffe 9201 du banc.
IF OBJECT_ID(N'v2.INFO_GREFFE') IS NULL CREATE TABLE v2.INFO_GREFFE (CODE_GREFFE varchar(4) NULL);
IF OBJECT_ID(N'v2.CODE_GREFFE') IS NULL
    CREATE TABLE v2.CODE_GREFFE (R_CODEGREFFE_VALEUR varchar(4) NOT NULL PRIMARY KEY, R_CODEGREFFE_TYPE_GREFFE varchar(15) NULL);
IF OBJECT_ID(N'v2.TYPE_GREFFE') IS NULL
    CREATE TABLE v2.TYPE_GREFFE (R_TYPEGREFFE_VALEUR varchar(15) NOT NULL PRIMARY KEY, R_TYPEGREFFE_NOM_GREFFE_MAJ varchar(100) NULL);
IF OBJECT_ID(N'v2.PARAM_EDITIONS') IS NULL CREATE TABLE v2.PARAM_EDITIONS (PRMED_DE_NOM_MAJ varchar(128) NULL);
IF COL_LENGTH('v2.PARAMETRE_EDITION', 'PRMED_CODE_DOCUMENT') IS NULL ALTER TABLE v2.PARAMETRE_EDITION ADD PRMED_CODE_DOCUMENT varchar(20) NULL;
IF COL_LENGTH('v2.PARAMETRE_EDITION', 'PRMED_IMPRESSION') IS NULL ALTER TABLE v2.PARAMETRE_EDITION ADD PRMED_IMPRESSION bit NULL;

EXEC sp_executesql N'
IF NOT EXISTS (SELECT 1 FROM v2.INFO_GREFFE) INSERT INTO v2.INFO_GREFFE (CODE_GREFFE) VALUES (''9201'');
IF NOT EXISTS (SELECT 1 FROM v2.CODE_GREFFE WHERE R_CODEGREFFE_VALEUR = ''9201'')
    INSERT INTO v2.CODE_GREFFE (R_CODEGREFFE_VALEUR, R_CODEGREFFE_TYPE_GREFFE) VALUES (''9201'', ''C'');
IF NOT EXISTS (SELECT 1 FROM v2.TYPE_GREFFE WHERE R_TYPEGREFFE_VALEUR = ''C'')
    INSERT INTO v2.TYPE_GREFFE (R_TYPEGREFFE_VALEUR, R_TYPEGREFFE_NOM_GREFFE_MAJ) VALUES (''C'', ''GREFFE DU TRIBUNAL DE COMMERCE'');
-- « | » : la V2 le change en « <BR> » (RigGreffe.cs:1543).
IF NOT EXISTS (SELECT 1 FROM v2.PARAM_EDITIONS) INSERT INTO v2.PARAM_EDITIONS (PRMED_DE_NOM_MAJ) VALUES (''DU BANC|ONZE'');
INSERT INTO v2.TYPE_BODACC (R_TYPEBODACC_VALEUR, R_TYPEBODACC_LIBELLE_ECRAN)
SELECT v, l FROM (VALUES (''P1'', N''Jgt ouverture du banc''), (''P2'', N''Jgt rectifié du banc'')) AS t(v, l)
WHERE NOT EXISTS (SELECT 1 FROM v2.TYPE_BODACC AS x WHERE x.R_TYPEBODACC_VALEUR = t.v);
IF NOT EXISTS (SELECT 1 FROM v2.TYPE_VOIE WHERE R_TYPEVOIE_VALEUR = ''AV11'')
    INSERT INTO v2.TYPE_VOIE (R_TYPEVOIE_VALEUR, R_TYPEVOIE_LIBELLE_ECRAN) VALUES (''AV11'', ''avenue'');
-- Les quatre reglages d''edition de RIG_DEV (PARAMETRE_EDITION, lus le 27/11/2026), leur liste telle quelle.
INSERT INTO v2.PARAMETRE_EDITION (PRMED_CODE, PRMED_LIBELLE, PRMED_LISTE, PRMED_CODE_MAQUETTE, PRMED_TYPE_GENERATION, PRMED_IMPRESSION, PRMED_CODE_DOCUMENT)
SELECT v.Code, v.Libelle, v.Liste, v.Maquette, v.TypeGen, 1, v.Doc FROM (VALUES
    (''LISTE_REJETS_BODACC'', N''Liste des rejets du BODACC'', ''LOT2_LISTE_REJETS'', ''FUSION_CRYSTAL'', NULL,
     N''<PARAMETRES TYPE_GENERATION="FUSION_CRYSTAL" LIBELLE_DOCUMENT="Liste des rejets du BODACC" CODE_MAQUETTE="LOT2_LISTE_REJETS" GROUPAGE_AUTOMATIQUE="0" NUM_GROUPE_IMPRESSION="ListeRejetsBodacc" AFFICHER_AVANT_IMPRESSION="0" IMPRESSION="1" RECTO_VERSO="0" NOMBRE_EXEMPLAIRES="1" READ_ONLY="0" AGRAFAGE="0" NE_PAS_GENERER="0" NON_SUPPRESSIBLE="0" />''),
    (''LISTE_BODACC_QUALITE'', N''Liste des BODACC de qualité non conforme'', ''LOT2_LISTE_QUALITENC'', ''FUSION_CRYSTAL'', NULL,
     N''<PARAMETRES TYPE_GENERATION="FUSION_CRYSTAL" LIBELLE_DOCUMENT="Liste des BODACC de qualité non conforme" CODE_MAQUETTE="LOT2_LISTE_QUALITENC" GROUPAGE_AUTOMATIQUE="0" NUM_GROUPE_IMPRESSION="ListeRejetsBodacc" AFFICHER_AVANT_IMPRESSION="0" IMPRESSION="1" RECTO_VERSO="0" NOMBRE_EXEMPLAIRES="1" READ_ONLY="0" AGRAFAGE="0" NE_PAS_GENERER="0" NON_SUPPRESSIBLE="0" />''),
    (''CERTIF_BOD'', N''Certificat parution Bodacc'', ''3801_CERTIF_BOD'', ''FUSION_RIG'', ''BODAC'',
     N''<PARAMETRES CODE_DOCUMENT="BODAC" CODE_MAQUETTE="3801_CERTIF_BOD" AGRAFAGE="0" CODE_ENTITE_SOURCE="BODACC" CODE_PROCESSUS="EDT_CRTBOD" RECTO_VERSO="0" TYPE_GENERATION="FUSION_RIG" NOMBRE_EXEMPLAIRES="1" IMPRESSION="1" AFFICHER_AVANT_IMPRESSION="0" LIBELLE_DOCUMENT="Certificat parution Bodacc" READ_ONLY="0" NE_PAS_GENERER="0" GROUPAGE_AUTOMATIQUE="0" NON_SUPPRESSIBLE="0" />''),
    (''CERTIF_BODPR'', N''Certificat de parution Bodacc PR'', ''3801_CERTIF_BOD_PR'', ''FUSION_RIG'', ''BODAC'',
     N''<PARAMETRES CODE_DOCUMENT="BODAC" CODE_ENTITE_SOURCE="BODACC" CODE_PROCESSUS="EDT_CRTBPR" CODE_MAQUETTE="3801_CERTIF_BOD_PR" RECTO_VERSO="0" TYPE_GENERATION="FUSION_RIG" NOMBRE_EXEMPLAIRES="1" IMPRESSION="1" AFFICHER_AVANT_IMPRESSION="0" LIBELLE_DOCUMENT="Certificat de parution Bodacc PR" READ_ONLY="0" AGRAFAGE="0" NE_PAS_GENERER="0" GROUPAGE_AUTOMATIQUE="0" NON_SUPPRESSIBLE="0" />''))
    AS v (Code, Libelle, Maquette, TypeGen, Doc, Liste)
WHERE NOT EXISTS (SELECT 1 FROM v2.PARAMETRE_EDITION AS p WHERE p.PRMED_CODE = v.Code);
-- Le pays BEL (ADRBS_PAYS, :1643) distingue le PAYS du certificat du defaut FRA d''ENTITE ; la base du banc n''a pas de libelle de
-- pays (v2.PAYS des jeux PROC_DBE_*, sans R_PAYS_LIBELLE_ECRAN) : le bloc adresse n''a pas de ligne de pays (BlocAdresseAsync).
