-- Les destinataires du certificat (PARAMETRAGE CERTIF_BOD_DEST, repris dans soc.Reglage) : le mandataire judiciaire et le document interne.
IF EXISTS (SELECT 1 FROM soc.Reglage WHERE Code = ''CERTIF_BOD_DEST'')
    UPDATE soc.Reglage SET Valeur = ''MDJ;DI'', AuteurModif = ''banc'', DateModif = SYSDATETIME() WHERE Code = ''CERTIF_BOD_DEST'';
